export function getGuideNumerologyLocale(lang: LocaleCode): GuideNumLocale {
  return GUIDE_NUMEROLOGY_I18N[lang] ?? GUIDE_NUMEROLOGY_I18N.en;
}

export function getGuideVsLocale(lang: LocaleCode): GuideVsLocale {
  return GUIDE_VS_I18N[lang] ?? GUIDE_VS_I18N.en;
}

export function getBhagyankLocale(lang: LocaleCode): BhagyankNamankLocale {
  return BHAGYANK_UI_I18N[lang] ?? BHAGYANK_UI_I18N.en;
}

export function getNamankLocale(lang: LocaleCode): BhagyankNamankLocale {
  return NAMANK_UI_I18N[lang] ?? NAMANK_UI_I18N.en;
}

export function getNumerologyNumUi(lang: LocaleCode): NumerologyNumUi {
  return NUMEROLOGY_NUM_UI[lang] ?? NUMEROLOGY_NUM_UI.en;
}
